-- Fix: crm_roles.org_id was missing the default my_org_id() that every other
-- CRM table has, so client-side inserts (which never set org_id explicitly)
-- violated the NOT NULL constraint. This is why "Add Role" failed silently.
alter table crm_roles
  alter column org_id set default my_org_id();

-- Default permission sets for the seeded roles. Previously every seeded role
-- had permissions = '{}', meaning only profiles.role = 'admin' could do
-- anything gated by PermissionGate/usePermissions. These are sensible
-- starting points based on typical landscaping company role structure;
